import { webkit, devices } from 'playwright';
const b = await webkit.launch();
const c = await b.newContext({ ...devices['iPhone 13'], locale: 'sv-SE' });
const p = await c.newPage();
await p.goto('http://localhost:8765/index.html'); await p.waitForTimeout(1500);
console.log(await p.evaluate(() => window.radiocast.version));
await p.locator('.row', { hasText: "Mouv'" }).click(); await p.waitForTimeout(10000);
console.log('Mouv kort:', (await p.innerText('#np')).replace(/\s+/g, ' '));
await p.click('#npText'); await p.waitForTimeout(1500);
console.log('låtvy:', (await p.innerText('#sheetBody')).replace(/\s+/g, ' ').slice(0, 400));
await b.close();
